#!/usr/bin/env node
/**
 * context-menu@1 conformance (Brett, Nov 13 2026: context menus as one true source on axHub, Claude-generated by coder
 * level). The pure rules (core/engines/context-menus-rules.mjs) replayed against their fixture.
 *   node framework/spec/check-context-menus.mjs            check
 *   node framework/spec/check-context-menus.mjs --write    regenerate fixtures/context-menus.json's expected outputs
 *
 *   1. levels: four, ordered, higher = more items / deeper / more zones; zonesForLevel per level
 *   2. zones: ownerOfPath, mergeZones (implicit ones always present, reported pages merged), weightOf
 *   3. items: normalize (ids slugged + unique, separators trimmed), validate, slim (budget, rare folds first, depth cap)
 *   4. menu: normalizeMenu is idempotent and valid, validateMenu catches each broken field, assetIdOf fits asset@1
 *   5. Claude: buildPrompt (level brief, zones, actions, developer actions only at advanced), parseReply (fence / bare /
 *      wrapped), fromReply (unknown actions + zones dropped with warnings, default filled, per-level slimming)
 *   6. history: snapshot (no duplicate, cap), restoreFrom; diffMenus; filterMenus; matchPhrase (voice)
 */
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as R from '../core/engines/context-menus-rules.mjs';

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const FIX = join(ROOT, 'framework/spec/fixtures/context-menus.json');
const WRITE = process.argv.includes('--write');
const NOW = '2026-11-13T20:00:00.000Z';
let n = 0; const t = (name, fn) => { try { fn(); n += 1; } catch (e) { console.error(`✗ ${name}`); throw e; } };

const fixture = WRITE ? { $axf: 'context-menus-fixture@1', note: 'Generated by framework/spec/check-context-menus.mjs --write: expected outputs of the context-menu@1 rules. A port (Kotlin twin, PORTING.md) must produce the same.', cases: {} } : JSON.parse(readFileSync(FIX, 'utf8'));
const expect = (key, value) => {
  if (WRITE) { fixture.cases[key] = value; return; }
  assert.deepEqual(JSON.parse(JSON.stringify(value)), fixture.cases[key], `fixture case "${key}" differs (run --write when the change is intended)`);
};

/* 1. levels */
t('levels', () => {
  assert.deepEqual(R.LEVEL_IDS, ['beginner', 'amateur', 'pro', 'advanced']);
  const ls = Object.values(R.LEVELS);
  for (let i = 1; i < ls.length; i++) {
    assert.ok(ls[i].order > ls[i - 1].order && ls[i].perTarget > ls[i - 1].perTarget && ls[i].depth >= ls[i - 1].depth, `level ${ls[i].id} maps more meticulously than ${ls[i - 1].id}`);
  }
  assert.equal(R.LEVELS.beginner.zones, 'core'); assert.equal(R.LEVELS.advanced.zones, 'all'); assert.equal(R.LEVELS.advanced.developer, true); assert.equal(R.LEVELS.pro.developer, false);
  expect('levels', R.LEVELS);
});

/* 2. zones */
const scanned = [
  { id: 'asset-card', file: 'framework/react/components/DataCard.tsx', weight: 'common', files: ['framework/react/components/DataCard.tsx'] },
  { id: 'axf-todo-entry', file: 'apps/console-web/plugins/todo-manager/web/Todo.tsx', weight: 'rare' },
  { id: 'banner', file: 'apps/console-web/src/x.tsx', weight: 'core' },
];
const reported = [{ id: 'asset-card', pages: ['theme-manager'], elements: ['Skin card'] }, { id: 'live-only', label: 'Live only' }];
t('zones', () => {
  assert.deepEqual(R.ownerOfPath('apps/console-web/plugins/todo-manager/web/Todo.tsx'), { kind: 'plugin', id: 'todo-manager', app: 'console-web' });
  assert.deepEqual(R.ownerOfPath('framework/react/components/DataCard.tsx'), { kind: 'framework', id: 'framework', app: '' });
  assert.deepEqual(R.ownerOfPath('apps/console-web/src/App.tsx'), { kind: 'console', id: 'console-web', app: 'console-web' });
  assert.deepEqual(R.ownerOfPath('apps/amberx-droid/src/x.kt'), { kind: 'app', id: 'amberx-droid', app: 'amberx-droid' });
  const merged = R.mergeZones(scanned, reported);
  assert.ok(merged.some((z) => z.id === 'default' && z.implicit), 'implicit zones always present');
  const ac = merged.find((z) => z.id === 'asset-card');
  assert.deepEqual(ac.pages, ['theme-manager']); assert.deepEqual(ac.elements, ['Skin card']); assert.equal(ac.weight, 'common');
  assert.equal(merged[0].weight, 'core', 'core zones first');
  assert.equal(R.weightOf('banner'), 'core'); assert.equal(R.weightOf('x', 3), 'common'); assert.equal(R.weightOf('x', 1), 'rare');
  assert.deepEqual(R.zonesForLevel('beginner', merged).map((z) => z.weight).filter((w) => w !== 'core'), []);
  assert.equal(R.zonesForLevel('advanced', merged).length, merged.length);
  expect('mergeZones', merged);
});

/* 3. items */
t('items', () => {
  const raw = [{ id: 'S', separator: true }, { label: 'Open It', action: 'nav:home' }, { label: 'Open It', action: 'nav:settings' }, { id: 'bad', label: 'No action' }, { id: 's2', separator: true }, { id: 's3', separator: true }, { id: 'g', label: 'Group', items: [{ id: 'c', label: 'Copy', action: 'edit.copy', items: [{ id: 'deep', label: 'Deep', action: 'x.y' }] }] }, { id: 'tail', separator: true }];
  const items = R.normalizeItems(raw, 0, 1);
  assert.deepEqual(items.map((x) => x.id), ['open-it', 'open-it-2', 's2', 'g']);
  assert.equal(items[3].items[0].items, undefined, 'depth capped');
  assert.deepEqual(R.validateItems(items), []);
  assert.ok(R.validateItems([{ id: 'x' }]).length && R.validateItems([{ id: 'x', label: 'X', action: 'not an action!' }]).length);
  assert.equal(R.countItems(items), 4); assert.equal(R.depthOf(items), 1);
  const many = [1, 2, 3, 4, 5, 6, 7].map((i) => ({ id: `i${i}`, label: `I${i}`, action: 'a.b', ...(i === 2 ? { rare: true } : {}) }));
  const s = R.slim(many, 4, 1);
  assert.deepEqual(s.map((x) => x.id), ['i1', 'i3', 'i4', 'ctx-more-sep', 'more']);
  assert.deepEqual(s[4].items.map((x) => x.id), ['i2', 'i5', 'i6', 'i7'], 'rare first into More…, then the overflow in order');
  assert.ok(!('rare' in s[0]), 'rare marks never reach the asset');
  assert.deepEqual(R.slim(many.slice(0, 3), 4, 1).map((x) => x.id), ['i1', 'i2', 'i3'], 'within budget: unchanged');
  const flat = R.slim([{ id: 'g', label: 'G', items: [{ id: 'a', label: 'A', action: 'x.a' }, { id: 'b', label: 'B', action: 'x.b' }] }], 5, 0);
  assert.deepEqual(flat, [{ id: 'g', label: 'G', action: 'x.a' }], 'depth 0 flattens a group onto its first action');
  expect('normalizeItems', items); expect('slim', s);
});

/* 4. menu */
const rawMenu = { id: 'Console Web / Pro', level: 'pro', app: 'console-web', by: 'brett', asset: { name: 'Pro set', data: { variant: 'glass', targets: { default: [{ id: 'home', label: 'Home', icon: 'home', action: 'nav:home', shortcut: 'Ctrl+H' }], 'asset-card': [{ id: 'c', label: 'Copy id', action: 'console.copy-id' }] } } } };
t('menu', () => {
  const m = R.normalizeMenu(rawMenu, NOW);
  assert.equal(m.id, 'console-web-pro'); assert.equal(m.asset.id, 'ctx-console-web-pro'); assert.equal(m.asset.data.showShortcuts, true);
  assert.deepEqual(R.validateMenu(m), []);
  assert.deepEqual(R.normalizeMenu(m, NOW), m, 'idempotent');
  assert.ok(R.validateMenu({ ...m, level: 'ninja' }).length);
  assert.ok(R.validateMenu({ ...m, asset: { ...m.asset, data: { ...m.asset.data, targets: {} } } }).some((e) => e.includes('default')));
  assert.ok(R.validateMenu({ ...m, asset: { ...m.asset, data: { ...m.asset.data, variant: 'neon' } } }).length);
  assert.ok(R.validateMenu({ ...m, asset: { ...m.asset, id: 'Bad Id' } }).length);
  assert.ok(R.validateMenu(null).length);
  assert.match(R.assetIdOf('a'.repeat(80)), R.ASSET_ID_RE); assert.ok(R.assetIdOf('a'.repeat(80)).length <= 48);
  assert.deepEqual(R.summarize(m), { targets: 2, items: 2, depth: 0, zones: ['default', 'asset-card'] });
  const beginner = R.normalizeMenu({ id: 'b', level: 'beginner', asset: { data: { targets: { default: [] } } } }, NOW);
  assert.equal(beginner.asset.data.showShortcuts, false, 'level decides shortcuts when the asset does not say');
  expect('normalizeMenu', m);
});

/* 5. Claude */
const actions = [{ id: 'nav:home', label: 'Home' }, { id: 'nav:settings', label: 'Settings' }, { id: 'edit.copy', label: 'Copy', module: 'framework' }];
t('prompt', () => {
  const p = R.buildPrompt({ level: 'beginner', zones: scanned, actions });
  assert.ok(p.system.includes('BEGINNER') && p.system.includes('at most 5 visible items'));
  assert.deepEqual(p.zones, ['banner', 'default', 'toolbar'], 'beginner: core zones only');
  assert.ok(!p.actions.includes('console.inspect'), 'no developer actions below advanced');
  const a = R.buildPrompt({ level: 'advanced', zones: scanned, actions, page: 'theme-manager' });
  assert.ok(a.actions.includes('console.inspect') && a.actions.includes('ui-manager.open'), 'advanced adds developer actions');
  assert.ok(a.zones.includes('axf-todo-entry'), 'advanced maps rare zones');
  assert.ok(a.messages[0].content.includes('PAGE: theme-manager'));
  assert.ok(R.buildPrompt({ actions: [{ id: 'bad action!' }] }).actions.length === 0, 'bad action ids never reach the prompt');
  expect('prompt-beginner', p); expect('prompt-advanced', a);
});
const replyObj = { name: 'Basics', variant: 'compact', targets: {
  default: [{ id: 'home', label: 'Home', icon: 'home', action: 'nav:home' }, { id: 'bogus', label: 'Bogus', action: 'made.up' }, { id: 's', separator: true }, { id: 'copy', label: 'Copy', action: 'edit.copy', rare: true }, { id: 'a', label: 'A', action: 'nav:settings' }, { id: 'b', label: 'B', action: 'nav:settings' }, { id: 'c', label: 'C', action: 'nav:settings' }, { id: 'd', label: 'D', action: 'nav:settings' }],
  banner: [{ id: 'g', label: 'Group', items: [{ id: 'x', label: 'Home', action: 'nav:home' }, { id: 'y', label: 'Settings', action: 'nav:settings' }] }],
  nowhere: [{ id: 'q', label: 'Q', action: 'nav:home' }],
} };
t('reply', () => {
  assert.deepEqual(R.parseReply(`Sure!\n\`\`\`json\n${JSON.stringify(replyObj)}\n\`\`\`\nDone.`), replyObj, 'fenced');
  assert.deepEqual(R.parseReply(JSON.stringify(replyObj)), replyObj, 'bare');
  assert.deepEqual(R.parseReply(`Here: ${JSON.stringify(replyObj)} ok?`), replyObj, 'wrapped');
  assert.equal(R.parseReply('no json here'), null);
  const b = R.fromReply(replyObj, { level: 'beginner', zones: scanned, actions, by: 'test', model: 'm', now: NOW });
  assert.deepEqual(R.validateMenu(b.doc), []);
  assert.ok(b.warnings.some((w) => w.includes('made.up')) && b.warnings.some((w) => w.includes('nowhere')));
  const def = b.doc.asset.data.targets.default;
  assert.ok(def.filter((x) => !x.separator).length <= R.LEVELS.beginner.perTarget, 'slimmed to the beginner budget');
  assert.ok(def.find((x) => x.id === 'more')?.items.some((x) => x.id === 'copy'), 'rare item folded first');
  assert.equal(R.depthOf(b.doc.asset.data.targets.banner), 0, 'beginner: group flattened');
  assert.equal(b.doc.source, 'claude'); assert.equal(b.doc.id, 'console-web-beginner'); assert.equal(b.doc.asset.data.showShortcuts, false);
  const p = R.fromReply(replyObj, { level: 'pro', zones: scanned, actions, now: NOW });
  assert.equal(R.depthOf(p.doc.asset.data.targets.banner), 1, 'pro keeps one level of submenu');
  assert.equal(p.doc.asset.data.targets.default.find((x) => x.id === 'more'), undefined, 'pro budget holds everything');
  const empty = R.fromReply({ targets: { banner: [{ id: 'x', label: 'X', action: 'nav:home' }] } }, { level: 'pro', zones: scanned, actions, now: NOW });
  assert.ok(empty.doc.asset.data.targets.default.length && empty.warnings.some((w) => w.includes('default zone was empty')));
  assert.equal(R.fromReply('garbage', { zones: scanned, actions }).doc, null);
  expect('fromReply-beginner', b); expect('fromReply-pro', p);
});

/* 6. history, diff, filters, voice */
t('history', () => {
  const m = R.normalizeMenu(rawMenu, NOW);
  let h = R.snapshot(null, m, 'a', NOW);
  assert.equal(h.versions.length, 1);
  h = R.snapshot(h, m, 'a', NOW); assert.equal(h.versions.length, 1, 'same content: no duplicate');
  const m2 = { ...m, asset: { ...m.asset, data: { ...m.asset.data, targets: { default: [] } } } };
  h = R.snapshot(h, m2, 'b', NOW); assert.equal(h.versions.length, 2); assert.equal(h.versions[1].v, 2);
  for (let i = 0; i < 30; i++) h = R.snapshot(h, { ...m, asset: { ...m.asset, name: `v${i}` } }, 'c', NOW);
  assert.equal(h.versions.length, R.HISTORY_MAX, 'capped');
  assert.equal(R.restoreFrom(h, h.versions[0].v, NOW).asset.name, h.versions[0].doc.asset.name);
  assert.equal(R.restoreFrom(h, 999), null);
  const diff = R.diffMenus(m, m2);
  assert.deepEqual(diff.map((d) => [d.target, d.status]), [['asset-card', 'gone'], ['default', 'changed']]);
  assert.deepEqual(R.diffMenus(null, m).map((d) => d.status), ['new', 'new']);
  assert.deepEqual(R.diffMenus(m, m).map((d) => d.status), ['same', 'same']);
  const list = [m, R.normalizeMenu({ id: 'basics', level: 'beginner', app: 'amberx-droid', asset: { data: { targets: { default: [{ id: 'x', label: 'Zap', action: 'nav:home' }] } } } }, NOW)];
  assert.equal(R.normalizeMenu({ id: 'b' }, NOW).id, 'b-menu', 'a one-letter id is padded to fit asset@1');
  assert.deepEqual(R.filterMenus(list, { level: 'beginner' }).map((x) => x.id), ['basics']);
  assert.deepEqual(R.filterMenus(list, { app: 'console-web' }).map((x) => x.id), ['console-web-pro']);
  assert.deepEqual(R.filterMenus(list, { zone: 'asset-card' }).map((x) => x.id), ['console-web-pro']);
  assert.deepEqual(R.filterMenus(list, { q: 'zap' }).map((x) => x.id), ['basics']);
  assert.deepEqual(R.filterMenus(list, { q: 'ctrl+h pro' }).map((x) => x.id), ['console-web-pro']);
  expect('diff', diff);
});
t('voice', () => {
  const cases = { 'generate pro context menus': { op: 'generate', level: 'pro', app: 'console-web', preview: false }, 'make beginner menus for the console': { op: 'generate', level: 'beginner', app: 'console-web', preview: false }, 'build advanced coder context menus for amberx-droid': { op: 'generate', level: 'advanced', app: 'amberx-droid', preview: false }, 'preview amateur menus': { op: 'generate', level: 'amateur', app: 'console-web', preview: true }, 'create developer context menus': { op: 'generate', level: 'advanced', app: 'console-web', preview: false }, apply: { op: 'apply' }, 'apply the draft': { op: 'apply' }, 'list context menus': { op: 'list' }, 'show me the pro menus': { op: 'list', level: 'pro' }, 'use context menu console-web-pro': { op: 'use', id: 'console-web-pro' }, 'switch to menu basics': { op: 'use', id: 'basics' }, 'restore the menu': { op: 'restore' }, 'what time is it': null, '': null };
  for (const [s, want] of Object.entries(cases)) assert.deepEqual(R.matchPhrase(s), want, `"${s}"`);
  expect('voice', cases);
});

if (WRITE) { writeFileSync(FIX, `${JSON.stringify(fixture, null, 1)}\n`); console.log(`wrote ${FIX}`); }
console.log(`check-context-menus: ${n} groups passed`);
